import path from 'node:path';
import { writeFileSync, mkdirSync } from 'node:fs';

export const BUILD_MANIFEST_SCHEMA_VERSION = 1 as const;

export interface BuildManifestModule {
  /** Absolute or relative module identifier. */
  id: string;
  bytes: number;
}

export interface BuildManifestChunk {
  file: string;
  entry: boolean;
  initial: boolean;
  imports: string[];
  dynamicImports: string[];
  css: string[];
  modules: BuildManifestModule[];
  routes: string[];
}

export interface BuildManifestRoute {
  route: string;
  files: string[];
  initial: boolean;
}

export interface CodeUsageBuildManifest {
  schemaVersion: typeof BUILD_MANIFEST_SCHEMA_VERSION;
  buildTool: 'vite' | 'webpack' | 'other';
  generator: string;
  generatedAt: string;
  chunks: BuildManifestChunk[];
  routes: BuildManifestRoute[];
}

export function writeBuildManifest(outputDirectory: string, filename: string, manifest: CodeUsageBuildManifest): string {
  mkdirSync(outputDirectory, { recursive: true });
  const file = path.join(outputDirectory, filename);
  writeFileSync(file, `${JSON.stringify(manifest, null, 2)}\n`, 'utf8');
  return file;
}

export function routeFromEntryName(name: string): string {
  const withoutLoader = name.split('!').pop() ?? name;
  const cleaned = withoutLoader.replace(/\\/g, '/').replace(/[?#].*$/, '');
  const base = path.posix.basename(cleaned);
  if (/^(index|main|app|client|bundle)(\.|$)/i.test(base)) return '/';
  const withoutExtension = cleaned.replace(/\.(html?|js|mjs|css)$/i, '').replace(/^\.?\//, '');
  if (!withoutExtension) return '/';
  return `/${withoutExtension}`.replace(/\/+/g, '/');
}
