import {
  BUILD_MANIFEST_SCHEMA_VERSION,
  routeFromEntryName,
  writeBuildManifest,
  type BuildManifestChunk,
  type CodeUsageBuildManifest,
} from './build-manifest.js';

export interface CodeUsageMapWebpackPluginOptions {
  /** Manifest filename inside `output.path`. */
  filename?: string;
  /** Optional route ownership mapping: route → entrypoint name or file. */
  routeEntries?: Record<string, string>;
}

interface WebpackModuleLike {
  name?: string;
  identifier?: string;
  size?: number;
}

interface WebpackChunkLike {
  files?: string[];
  entry?: boolean;
  initial?: boolean;
  names?: string[];
  modules?: WebpackModuleLike[];
}

interface WebpackStatsJson {
  chunks?: WebpackChunkLike[];
  entrypoints?: Record<string, { assets?: Array<{ name?: string }>; chunks?: Array<string | number> }>;
}

interface WebpackCompilationLike {
  getStats(): {
    toJson(options: Record<string, unknown>): WebpackStatsJson;
  };
}

interface WebpackCompilerLike {
  options?: { output?: { path?: string } };
  hooks?: {
    afterEmit?: {
      tapPromise(name: string, callback: (compilation: WebpackCompilationLike) => Promise<void>): void;
      tap(name: string, callback: (compilation: WebpackCompilationLike) => void): void;
    };
  };
}

function moduleId(module: WebpackModuleLike): string {
  const raw = module.identifier ?? module.name ?? '';
  const withoutLoaders = raw.split('!').pop() ?? raw;
  return withoutLoaderPrefix(withoutLoaders);
}

function withoutLoaderPrefix(value: string): string {
  return value
    .replace(/^webpack:\/\/[^/]*\/?/, '')
    .replace(/^\.\//, '')
    .replace(/[?#].*$/, '');
}

/**
 * Official Webpack plugin. It writes entrypoint/chunk/CSS/module attribution
 * and route metadata after emit without adding code to the browser bundle.
 */
export class CodeUsageMapWebpackPlugin {
  readonly name = 'code-usage-map-webpack';
  private readonly filename: string;
  private readonly routeEntries: Record<string, string>;

  constructor(options: CodeUsageMapWebpackPluginOptions = {}) {
    this.filename = options.filename ?? 'code-usage-map.webpack.json';
    this.routeEntries = options.routeEntries ?? {};
  }

  apply(compiler: WebpackCompilerLike): void {
    const outputDirectory = compiler.options?.output?.path ?? process.cwd();
    const write = async (compilation: WebpackCompilationLike): Promise<void> => {
      const stats = compilation.getStats().toJson({
        all: false,
        assets: true,
        chunks: true,
        chunkModules: true,
        modules: true,
        nestedModules: true,
        entrypoints: true,
      });

      const chunks: BuildManifestChunk[] = (stats.chunks ?? []).map((chunk) => {
        const files = (chunk.files ?? []).map((file) => file.replaceAll('\\', '/'));
        const modules = (chunk.modules ?? [])
          .map((module) => ({ id: moduleId(module), bytes: module.size ?? 0 }))
          .filter((module) => module.id.length > 0)
          .sort((a, b) => b.bytes - a.bytes)
          .slice(0, 10_000);
        const names = chunk.names ?? [];
        const routes = chunk.entry
          ? names.length > 0
            ? names.map((name) => routeFromEntryName(name))
            : ['/']
          : [];
        return {
          file: files[0] ?? '',
          entry: Boolean(chunk.entry),
          initial: chunk.initial !== false,
          imports: [],
          dynamicImports: [],
          css: files.filter((file) => file.endsWith('.css')),
          modules,
          routes: [...new Set(routes)],
        };
      }).filter((chunk) => chunk.file !== '');

      const routes = new Map<string, Set<string>>();
      const assetsByEntryName = new Map<string, string[]>();
      for (const [entryName, entrypoint] of Object.entries(stats.entrypoints ?? {})) {
        const route = routeFromEntryName(entryName);
        const files = (entrypoint.assets ?? [])
          .map((asset) => asset.name)
          .filter((name): name is string => Boolean(name))
          .map((name) => name.replaceAll('\\', '/'));
        assetsByEntryName.set(entryName, files);
        const set = routes.get(route) ?? new Set<string>();
        for (const file of files) set.add(file);
        routes.set(route, set);
      }
      for (const [route, entry] of Object.entries(this.routeEntries)) {
        const set = routes.get(route) ?? new Set<string>();
        const files = assetsByEntryName.get(entry);
        if (files) for (const file of files) set.add(file);
        else set.add(entry);
        routes.set(route, set);
      }
      if (routes.size === 0) routes.set('/', new Set());

      const manifest: CodeUsageBuildManifest = {
        schemaVersion: BUILD_MANIFEST_SCHEMA_VERSION,
        buildTool: 'webpack',
        generator: '@codewithrajat/code-usage-map/webpack',
        generatedAt: new Date().toISOString(),
        chunks,
        routes: [...routes.entries()].map(([route, files]) => ({
          route,
          files: [...files],
          initial: true,
        })),
      };
      writeBuildManifest(outputDirectory, this.filename, manifest);
    };

    if (compiler.hooks?.afterEmit?.tapPromise) {
      compiler.hooks.afterEmit.tapPromise(this.name, write);
    } else if (compiler.hooks?.afterEmit?.tap) {
      compiler.hooks.afterEmit.tap(this.name, (compilation) => {
        void write(compilation).catch(() => undefined);
      });
    }
  }
}
